/**
 * A Binder controls all aspects of a single form.
 * Typically, it is used to get and set the form value,
 * access the form model, validate, reset, and submit the form.
 *
 * @typeParam T - Type of the value that binds to a form
 * @typeParam M - Type of the model that describes the structure of the value
 */
export class Binder<M extends ProvisionalModel> extends BinderRoot<M> {
  declare readonly ['constructor']: Omit<typeof Binder<M>, 'constructor'>;

  context: Element;

  /**
   *
   * @param context - The form view component instance to update.
   * @param modelClass - The constructor (the class reference) of the form model. The Binder instantiates the top-level model
   * @param config - The options object, which can be used to config the onChange and onSubmit callbacks.
   *
   * ```
   * binder = new Binder(orderView, OrderModel);
   * or
   * binder = new Binder(orderView, OrderModel, {onSubmit: async (order) => {endpoint.save(order)}});
   * ```
   */
  constructor(context: Element, modelClass: ProvisionalModelConstructor<M>, config?: BinderConfiguration<Value<M>>) {
    const changeCallback =
      config?.onChange ??
      (typeof (context as LitElement).requestUpdate === 'function'
        ? () => (context as LitElement).requestUpdate()
        : undefined);

    super(modelClass, {
      ...(config ?? {}),
      onChange: changeCallback,
      context,
    });
    this.context = context;
  }
}

  if (handle.exited) {
    out.exitCode = handle.exitCode ?? null
    out.exitSignal = signalNameOf(handle.exitSignal)
  }
  return out
}

/**
 * The agent terminal registry. The constructor takes the resolved shell
 * binary (the same `defaultShell()` the UI-tab registry uses) and runs the
 * spawn-helper chmod fix once at construction so the first agent terminal
 * does not race a lazy fixer.
 */
export class AgentPtyRegistry {
  private readonly sessions = new Map<string, AgentTerminalHandle>()
  private readonly changeListeners = new Set<() => void>()

  constructor(
    private readonly shell: string,
    private readonly shellArgs: string[] = [],
    /** The loaded node-pty module (injected so a broken install degrades instead of crashing the plugin). */
    private readonly nodePty: NodePtyModule = loadRequiredNodePty(),
  ) {
    ensureSpawnHelper()
  }

  /**
   * Spawn one agent terminal: start the shell in `cwd`, then write
   * `command + '\n'` to stdin so the command runs in the fresh shell. The
   * terminal stays alive after the command exits — the model can send more
   * input through `terminal_send` until it calls `terminal_close` or the
   * user closes the sidebar tab. An empty `command` spawns a bare shell.
   * @returns the new handle's uuid (the model-facing opaque id).
   */
  create(
    sessionId: string,
    title: string,
    command: string,
    cwd: string,
    cols = 80,
    rows = 24,
    shell?: string,
    shellArgs?: string[],
  ): string {
    const uuid = randomUUID()
    const dims = clampDims(cols, rows)
    const pty = this.nodePty.spawn(shell ?? this.shell, shellSpawnArgs(shellArgs ?? this.shellArgs), {
      name: 'xterm-256color',
      cols: dims.cols,
      rows: dims.rows,
      cwd,
      env: { ...process.env },
    })
    const handle: AgentTerminalHandle = {
      uuid,
      sessionId,
      title,
      command,
      cwd,
      pty,
      transcript: '',
      exited: false,
    }
    pty.onData((data) => {
      handle.transcript += data
      if (handle.transcript.length > TRANSCRIPT_LIMIT) {
        handle.transcript = handle.transcript.slice(handle.transcript.length - TRANSCRIPT_LIMIT)
      }
    })
    pty.onExit(({ exitCode, signal }) => {
      handle.exited = true
      handle.exitCode = exitCode
      handle.exitSignal = signal
      this.notify()
    })
    if (command !== '') {
      // Write the command + Enter so it runs in the freshly spawned shell.
      // Use \r (carriage return) — the actual character a terminal sends for
      // the Enter key — not \n (line feed). PowerShell treats a bare \n as a
      // soft line break (continuation prompt ">>") rather than a command
      // submit; \r is the cross-shell Enter semantics on both POSIX and Windows.
      try {
        pty.write(`${command}\r`)
      } catch {
        // A spawn that failed between onData and onExit surfaces its own
        // exit; the create call still returns the uuid so the model can
        // read the transcript and see the failure.
      }
    }
    this.sessions.set(uuid, handle)
    this.notify()

    small_object_allocator alloc{};
    r1::enqueue(*alloc.new_object<enqueue_task<typename std::decay<F>::type>>(std::forward<F>(f), alloc), ta);
}
/** 1-to-1 proxy representation class of scheduler's arena
 * Constructors set up settings only, real construction is deferred till the first method invocation
 * Destructor only removes one of the references to the inner arena representation.
 * Final destruction happens when all the references (and the work) are gone.
 */
class task_arena : public task_arena_base {

    void mark_initialized() {
        __TBB_ASSERT( my_arena.load(std::memory_order_relaxed), "task_arena initialization is incomplete" );
        my_initialization_state.store(do_once_state::initialized, std::memory_order_release);
    }

    template<typename R, typename F>
    R execute_impl(F& f) {
        initialize();
        task_arena_function<F, R> func(f);
        r1::execute(*this, func);
        return func.consume_result();
    }

    d2::task_group_status wait_for_impl(d2::task_group& tg) {
        d2::task_group_status status = d2::task_group_status::not_complete;
        d2::wait_delegate wd{tg, status};
        r1::execute(*this, wd);
        __TBB_ASSERT(status != d2::task_group_status::not_complete,
                "unexpected premature exit from wait_for: task group status is still not complete");
        return status;
    }
#if __TBB_PREVIEW_TASK_GROUP_EXTENSIONS
    d2::task_group_status wait_for_impl(d2::task_completion_handle& comp_handle) {
        d2::task_group_status status = d2::task_group_status::not_complete;
        d2::wait_completion_delegate wd{comp_handle, status};
        r1::execute(*this, wd);
        __TBB_ASSERT(status != d2::task_group_status::not_complete,
                "unexpected premature exit from wait_for: task status is still not complete");
        return status;
    }
#endif

public:
    //! Creates task_arena with certain concurrency limits
    /** Sets up settings only, real construction is deferred till the first method invocation
     *  @arg max_concurrency specifies total number of slots in arena where threads work
     *  @arg reserved_slots specifies number of slots to be used by external threads only.
     *       Value of 1 is default and reflects behavior of implicit arenas.
     **/
    task_arena(int max_concurrency_ = automatic, unsigned reserved_slots = 1,
               priority a_priority = priority::normal, leave_policy lp = leave_policy::automatic
    )
        : task_arena_base(max_concurrency_, reserved_slots, a_priority , lp)
    {}

}

// checkReadable returns an error when the path cannot be read as a configuration file. It reports
// os.ErrNotExist only when nothing is at the path, so that callers can tell a project that was
// never initialized from one whose configuration path holds something else.
func checkReadable(fs afero.Fs, path string) error {
	// The link is followed, so a link to a configuration file is read as one.
	class, err := classify(fs, path)
	if err != nil {
		return err
	}

	if class == pathMissing {
		// A link with a missing target also reads as missing, so report the link instead.
		linkClass, linkErr := classifyNoFollow(fs, path)
		if linkErr != nil || linkClass != pathSymbolicLink {
			return fmt.Errorf("failed to read %q file: %w", path, os.ErrNotExist)
		}
		class = linkClass
	}

	if class != pathRegularFile {
		return fmt.Errorf("%q is %s", path, class)
	}

	return nil
}

// checkSavePath verifies that the path can be used to save a configuration. It accepts a missing
// path for a new configuration and a regular file for an update. Other path types are rejected
// when the filesystem can identify them.
func checkSavePath(fs afero.Fs, path string, mustNotExist bool) error {
	class, err := classifyNoFollow(fs, path)
	if err != nil {
		return err
	}

	switch class {
	case pathRegularFile:
		if mustNotExist {
			return fmt.Errorf("configuration already exists in %q", path)
		}
		return nil
	case pathSymbolicLink, pathDirectory, pathIrregularFile:
		return fmt.Errorf("cannot save configuration to %q: path is %s", path, class)
	default:
		return nil
	}
}

// LoadFrom implements store.Store interface
func (s *yamlStore) LoadFrom(path string) error {
	s.mustNotExist = false

	// Only a regular file can carry configuration data.
	if err := checkReadable(s.fs, path); err != nil {
		return store.LoadError{Err: err}
	}

	// Read the file
	in, err := afero.ReadFile(s.fs, path)
	if err != nil {
		return store.LoadError{Err: fmt.Errorf("failed to read %q file: %w", path, err)}
	}

	// Check the file version
	var versioned versionedConfig
	if err = yaml.Unmarshal(in, &versioned); err != nil {
		return store.LoadError{Err: fmt.Errorf("failed to determine config version: %w", err)}
	}

	// Create the config object
	var cfg config.Config
	cfg, err = config.New(versioned.Version)
	if err != nil {
		return store.LoadError{Err: fmt.Errorf("failed to create config for version %q: %w", versioned.Version, err)}
	}

	// Unmarshal the file content
	if err := cfg.UnmarshalYAML(in); err != nil {
		return store.LoadError{Err: fmt.Errorf("failed to unmarshal config at %q: %w", path, err)}
	}

	s.cfg = cfg
	return nil
}

